// ============================================
// VALIDATION INPUT - RFC-014 Compatible
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (for tracing only, NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Extract image ---
const imageUrl_raw = ctx.image_url || ctx.file_url || body.image_url;
const imageBase64_raw = ctx.image_base64 || ctx.file_base64 || body.image_base64;
const fileType = ctx.file_type || body.file_type;

// --- Extract API key ---
const mistralKey = body.mistral_api_key 
  || ctx.mistral_api_key 
  || body.plugin_context?.api_keys?.mistral 
  || ctx.plugin_context?.api_keys?.mistral;

// --- Extract context fields ---
const projectId = ctx.project_id || body.project_id || body.plugin_context?.plugin_id;
const channelId = ctx.channel_id || body.channel_id;

// --- Validation ---
const hasImage = !!(imageUrl_raw || imageBase64_raw);
const hasMistralKey = !!mistralKey;

if (!hasImage) errors.push('image_url ou image_base64 requis');
if (!hasMistralKey) errors.push('mistral_api_key requis');

// --- Mise en page (azy.daily#363) : options relayées par MCP ---
// extract_header_footer (défaut true : en-têtes et pieds courants sortis du markdown),
// include_blocks (défaut false), table_format ("markdown" défaut | "html").
const booleen363 = (v, defaut) => {
  if (v === undefined || v === null || v === '') return defaut;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  if (['true', '1', 'yes', 'oui'].includes(s)) return true;
  if (['false', '0', 'no', 'non'].includes(s)) return false;
  return null;
};
const option363 = nom => (body[nom] !== undefined ? body[nom] : ctx[nom]);
const extractHeaderFooter = booleen363(option363('extract_header_footer'), true);
const includeBlocks = booleen363(option363('include_blocks'), false);
const tableFormatBrut = option363('table_format');
const tableFormat = (tableFormatBrut === undefined || tableFormatBrut === null || tableFormatBrut === '')
  ? 'markdown' : String(tableFormatBrut).trim().toLowerCase();
if (extractHeaderFooter === null) errors.push('extract_header_footer invalide (true ou false attendu)');
if (includeBlocks === null) errors.push('include_blocks invalide (true ou false attendu)');
if (!['markdown', 'html'].includes(tableFormat)) errors.push(`table_format invalide : '${tableFormatBrut}' (markdown ou html)`);
// Corps Mistral construit ici (jamais de valeur insérée dans un JSON écrit en dur).
// table_format "markdown" n'est PAS envoyé : sans ce champ, Mistral laisse le tableau
// dans le markdown (mesuré) ; "html" le sort dans tables[] et met un lien à sa place.
const optionsMistral363 = {};
if (extractHeaderFooter) { optionsMistral363.extract_header = true; optionsMistral363.extract_footer = true; }
if (includeBlocks) optionsMistral363.include_blocks = true;
if (tableFormat === 'html') optionsMistral363.table_format = 'html';

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

// --- Detect MIME type ---
function detectMimeFromBase64(base64) {
  const prefix = base64.substring(0, 20);
  if (prefix.startsWith('/9j/')) return 'image/jpeg';
  if (prefix.startsWith('iVBOR')) return 'image/png';
  if (prefix.startsWith('R0lG')) return 'image/gif';
  if (prefix.startsWith('UklGR')) return 'image/webp';
  return 'image/png';
}

function getMimeFromExtension(ext) {
  const map = {
    'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
    'png': 'image/png', 'gif': 'image/gif',
    'webp': 'image/webp', 'bmp': 'image/bmp'
  };
  return map[(ext || '').toLowerCase()] || null;
}

// --- Prepare image URL ---
let imageUrl = '';
let detectedMime = 'image/png';

if (imageUrl_raw) {
  imageUrl = imageUrl_raw;
} else if (imageBase64_raw) {
  detectedMime = fileType ? (getMimeFromExtension(fileType) || 'image/png') : detectMimeFromBase64(imageBase64_raw);
  imageUrl = 'data:' + detectedMime + ';base64,' + imageBase64_raw;
}

return {
  valid: true,
  imageUrl: imageUrl,
  detectedMime: detectedMime,
  mistralApiKey: mistralKey,
// azy.daily#363, décision PO du 21/09 : les figures sont rendues, SANS option. Défaut à true —
// la route /api/ocr/extract refuse `include_images` (422), donc sans ce défaut images[] serait
// toujours vide chez chat.api. `??` : un appelant qui envoie false garde des réponses légères.
  includeImages: body.include_images ?? ctx.include_images ?? true,
  extractHeaderFooter: extractHeaderFooter,
  includeBlocks: includeBlocks,
  tableFormat: tableFormat,
  mistralRequest: Object.assign({
    model: 'mistral-ocr-latest',
    document: { type: 'image_url', image_url: imageUrl },
    include_image_base64: body.include_images ?? ctx.include_images ?? true
  }, optionsMistral363),
  source: imageUrl_raw ? 'url' : 'base64',
  context: {
    project_id: projectId,
    guild_id: guildId,
    user_id: userId,
    channel_id: channelId
  },
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// FORMAT SUCCESS/ERROR RESPONSE - with _trace
// ============================================

// ── azy.daily#363 — détail par page (bloc commun, identique dans chaque nœud Mistral) ──
// Forme fixée par l'api : { index, markdown, header, footer, page_width, page_height, dpi,
// blocks[] (seulement si include_blocks), tables[] (seulement si table_format "html") }.
// Types de blocs : text → paragraph, image → figure, equation → formula ; les autres
// (title, list, table, caption, code, references, aside_text, signature…) gardent leur nom,
// y compris un type inconnu. header et footer ne sont PAS des blocs : ils vivent dans les
// champs de page. bbox mesurée en pixels de la page : Mistral donne deux coins
// (top_left_x/y, bottom_right_x/y), on rend { x, y, width, height }.
const TYPES_BLOCS_363 = { text: 'paragraph', image: 'figure', equation: 'formula' };
const HORS_BLOCS_363 = ['header', 'footer'];
const nombre363 = v => (typeof v === 'number' && Number.isFinite(v) ? v : null);
const texte363 = v => (typeof v === 'string' && v !== '' ? v : null);
const HTML_TABLE_363 = /^\s*<table[\s>]/i;

function bbox363(b) {
  const x1 = nombre363(b.top_left_x);
  const y1 = nombre363(b.top_left_y);
  const x2 = nombre363(b.bottom_right_x);
  const y2 = nombre363(b.bottom_right_y);
  if (x1 === null || y1 === null || x2 === null || y2 === null) return null;
  return { x: x1, y: y1, width: x2 - x1, height: y2 - y1 };
}

function blocs363(page) {
  const tablesHtml = {};
  (Array.isArray(page.tables) ? page.tables : []).forEach(t => {
    if (t && t.id && typeof t.content === 'string' && HTML_TABLE_363.test(t.content)) tablesHtml[t.id] = t.content;
  });
  return (Array.isArray(page.blocks) ? page.blocks : [])
    .filter(b => b && typeof b === 'object' && !HORS_BLOCS_363.includes(b.type))
    .map(b => {
      const type = TYPES_BLOCS_363[b.type] || texte363(b.type) || 'paragraph';
      const texte = typeof b.content === 'string' ? b.content : '';
      let tableHtml = null;
      if (type === 'table') tableHtml = HTML_TABLE_363.test(texte) ? texte : (tablesHtml[b.table_id] || null);
      return { block_type: type, text: texte, bbox: bbox363(b), confidence: null, table_html: tableHtml };
    });
}

function detailPage363(page, position, options) {
  const p = page && typeof page === 'object' ? page : {};
  const dims = p.dimensions && typeof p.dimensions === 'object' ? p.dimensions : {};
  const detail = {
    index: (Number.isInteger(p.index) ? p.index : position) + 1,
    markdown: typeof p.markdown === 'string' ? p.markdown : '',
    header: texte363(p.header),
    footer: texte363(p.footer),
    page_width: nombre363(dims.width),
    page_height: nombre363(dims.height),
    dpi: nombre363(dims.dpi),
    // Figures de la page, TELLES QUE Mistral les rend (id, coins, image_base64 en data-URL) :
    // chat.api les stocke et réécrit les liens du markdown. Verbatim, aucune transformation.
    // [] quand la page n'a pas de figure — le champ ne manque jamais (azy.daily#363).
    images: Array.isArray(p.images) ? p.images : []
  };
  if (options.includeBlocks) detail.blocks = blocs363(p);
  if (options.tableFormat === 'html') {
    detail.tables = (Array.isArray(p.tables) ? p.tables : []).map(t => ({
      id: String((t && t.id) || '').replace(/\.html$/i, ''),
      format: (t && t.format) || 'html',
      content: t && typeof t.content === 'string' ? t.content : ''
    }));
  }
  return detail;
}

// Statut HTTP : neverError le fournit ; sur une erreur de transport (onError), n8n n'émet
// qu'un message « 500 - {...} » sans statusCode.
function statutHttp363(entree) {
  if (typeof entree.statusCode === 'number') return entree.statusCode;
  const brut = String((entree.error && entree.error.message) || entree.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  if (m) return parseInt(m[1], 10);
  return entree.error ? 502 : 200;
}
// ── fin du bloc commun #363 ──

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime;
const options = { includeBlocks: prevData.includeBlocks === true, tableFormat: prevData.tableFormat };

const data = input.body || input;
const statusCode = statutHttp363(input);

// --- Check for API error ---
if (statusCode >= 400 || input.error) {
  const errorMessage = data.message || data.error?.message || input.error?.message || 'Mistral API error';
  return {
    success: false,
    error: {
      code: 'OCR_API_ERROR',
      message: errorMessage,
      http_status: statusCode >= 400 ? statusCode : 500
    },
    _trace: {
      service_response: { error: errorMessage, http_status: statusCode },
      provider: 'mistral',
      mode: 'error',
      latency_ms: Date.now() - startTime,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request
    },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  };
}

// --- Extract text from pages ---
const pages = data.pages || [];
const text = pages.map(p => p.markdown).join('\n\n') || '';

return {
  success: true,
  data: {
    text: text,
    pages: pages,
    model: data.model || 'mistral-ocr-latest',
    source: prevData.source,
    page_details: pages.map((p, idx) => detailPage363(p, idx, options)),
    warnings: []
  },
  meta: {
    provider: 'mistral',
    usage: {
      pages_processed: data.usage_info?.pages_processed || 1,
      doc_size_bytes: data.usage_info?.doc_size_bytes || 0
    }
  },
  _trace: {
    service_response: {
      pages_processed: data.usage_info?.pages_processed || pages.length,
      text_length: text.length
    },
    provider: 'mistral',
    mode: 'ocr',
    latency_ms: Date.now() - startTime,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  },
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  user_request: prevData.user_request
};

// ============================================
// BUILD VALIDATION ERROR - with _trace
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

